-- Keep the oldest live request per game before the unique index; the others are released.
UPDATE `integration_requests` SET `game_id` = NULL, `status` = 'failed', `error_message` = 'Game is already linked to another request.' WHERE `game_id` IS NOT NULL AND `status` <> 'cancelled' AND EXISTS (SELECT 1 FROM `integration_requests` AS `other` WHERE `other`.`user_id` = `integration_requests`.`user_id` AND `other`.`provider` = `integration_requests`.`provider` AND `other`.`game_id` = `integration_requests`.`game_id` AND `other`.`status` <> 'cancelled' AND (COALESCE(`other`.`created_at`, 0) < COALESCE(`integration_requests`.`created_at`, 0) OR (COALESCE(`other`.`created_at`, 0) = COALESCE(`integration_requests`.`created_at`, 0) AND `other`.`id` < `integration_requests`.`id`)));--> statement-breakpoint
CREATE UNIQUE INDEX `integration_requests_live_game_idx` ON `integration_requests` (`user_id`,`provider`,`game_id`) WHERE "integration_requests"."game_id" is not null and "integration_requests"."status" <> 'cancelled';